mapper.delete:
delete from INTERF_PROD_LADDER_DETAIL
where PRODID = #{prodid,jdbcType=VARCHAR}
  and CDATE = #{cdate,jdbcType=VARCHAR}
  and INTERF_ID = #{interfId,jdbcType=VARCHAR}

delete from INTERF_BRANCH
where PRODID = #{prodid,jdbcType=VARCHAR}
  and CDATE = #{cdate,jdbcType=VARCHAR}
  and INTERF_ID = #{interfId,jdbcType=VARCHAR}

delete from INTERF_PROD_INFO
where PRODID = #{prodid,jdbcType=VARCHAR}
  and CDATE = #{cdate,jdbcType=VARCHAR}
  and INTERF_ID = #{interfId,jdbcType=VARCHAR}

mapper.select:
SELECT lvl1.PRODID as prodid,
       lvl1.CDATE as cdate,
       lvl1.REFADDRATE as refaddrate,
       lvl1.ACCOUNTAMOUNTBYRATE as accountamountbyrate,
       lvl1.INTERF_ID as interfId
FROM INTERF_PROD_LADDER_DETAIL lvl1
WHERE lvl1.PRODID = #{prodid,jdbcType=VARCHAR}
  and lvl1.INTERF_ID = #{interfId,jdbcType=VARCHAR}
  and lvl1.REFADDRATE = #{refaddrate,jdbcType=VARCHAR}
  and lvl1.CDATE = (SELECT MAX(lvl2.CDATE) FROM INTERF_PROD_LADDER_DETAIL lvl2
               WHERE lvl2.PRODID = #{prodid,jdbcType=VARCHAR}
               and lvl2.INTERF_ID = #{interfId,jdbcType=VARCHAR}
               and lvl2.REFADDRATE = #{refaddrate,jdbcType=VARCHAR}
               and lvl2.CDATE < #{cdate,jdbcType=VARCHAR})
